import Foundation
import UserNotifications

/// Selective cleanup used by both the original Deflector automation callback
/// and the Shortcuts Hub acknowledgment intent.
///
/// Only tagged notifications generated by the integrated DeflectionService
/// are eligible. Other Bark notifications are never removed.
enum HubNotificationCleanup {
    static let originKey = "shortcutsHub.origin"
    static let originValue = "Deflector"

    /// Removes a single matching delivered notification.
    ///
    /// - Parameter identifier: When non-empty, remove ONLY this identifier;
    ///   no fallback is attempted if it is not a tagged Deflector notification.
    ///   Otherwise remove the newest tagged Deflector notification.
    /// - Returns: The removed identifier, or nil if there was no eligible match.
    @discardableResult
    static func removeDeflection(identifier: String? = nil) async -> String? {
        let center = UNUserNotificationCenter.current()
        let delivered = await center.deliveredNotifications()
        let eligible = delivered.filter { notification in
            notification.request.content.title == "Deflection" &&
                notification.request.content.userInfo[originKey] as? String == originValue
        }

        let requested = identifier?.trimmingCharacters(in: .whitespacesAndNewlines)
        let target: UNNotification?
        if let requested, !requested.isEmpty {
            target = eligible.first(where: { $0.request.identifier == requested })
        } else {
            target = eligible.max { first, second in
                if first.date != second.date {
                    return first.date < second.date
                }
                return first.request.identifier < second.request.identifier
            }
        }

        guard let target else { return nil }
        let chosenID = target.request.identifier
        center.removeDeliveredNotifications(withIdentifiers: [chosenID])
        return chosenID
    }
}
